import requests, xml.etree.ElementTree as ET, re
pmid='25070676'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':pmid,'retmode':'xml'},timeout=30)
root=ET.fromstring(r.text)
for tag in ['ArticleTitle','AbstractText','Year','MedlinePgn','ELocationID']:
    vals=[]
    for e in root.iter(tag):
        txt=''.join(e.itertext()).strip()
        if txt: vals.append(txt)
    if vals: print(tag, vals)
print('DOI', [e.attrib.get('ValidYN')+':'+(e.text or '') for e in root.iter('ELocationID')])
print('JOURNAL', [''.join(e.itertext()).strip() for e in root.iter('Title')][:3])

import requests, re
pmid='25070676'
for url in [f'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:{pmid}&format=json',f'https://www.ebi.ac.uk/europepmc/webservices/rest/{pmid}/fullTextXML']:
    r=requests.get(url,timeout=30)
    print('URL',url,'STATUS',r.status_code,'LEN',len(r.text))
    print(r.text[:300])
    if 'fullTextXML' in url and r.status_code==200:
        text=re.sub('<[^>]+>',' ',r.text)
        text=re.sub(r'\s+',' ',text)
        for pat in ['sample size','sample-size','patients per arm','per arm','80%','90%','progression rate']:
            hits=[m.start() for m in re.finditer(pat,text,re.I)]
            print('\nPAT',pat,'N',len(hits))
            for p in hits[:8]: print(text[max(0,p-250):p+500])

